import{_ as t}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as o,o as d,c as r,a2 as a}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.CvamBllE.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.anLeyFCI.png",i="/newx-doc/assets/%E8%A1%A8%E5%85%B3%E7%B3%BB.DngSUdFs.png",n="/newx-doc/assets/wms-preview.BNVmzkqo.png",y=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"wms/build.md","filePath":"wms/build.md","lastUpdated":null}'),l={name:"wms/build.md"};function m(p,e,u,_,h,g){return d(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>WMS 系统，后端由 <code>yudao-module-wms</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>wms</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-wms</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-wms</code> 模块</li><li>第二步，导入 WMS 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-wms</code> 模块的注释。如下图所示：</p><p><img src="'+s+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-wms</code> 模块。如下图所示：</p><p><img src="'+c+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+t+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/wms.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ wms.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+i+'" alt="导入数据库"></p><p>以 <code>wms_</code> 作为前缀的表，就是 WMS 模块的表，一共 <strong>16</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>子前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>wms_warehouse</code> / <code>wms_item*</code> / <code>wms_merchant</code></td><td>基础数据</td><td>6</td></tr><tr><td><code>wms_inventory*</code></td><td>库存管理</td><td>2</td></tr><tr><td><code>wms_receipt_order*</code></td><td>入库单</td><td>2</td></tr><tr><td><code>wms_shipment_order*</code></td><td>出库单</td><td>2</td></tr><tr><td><code>wms_movement_order*</code></td><td>移库单</td><td>2</td></tr><tr><td><code>wms_check_order*</code></td><td>盘库单</td><td>2</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 WMS 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+n+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了 WMS 的功能 🙂</p><h2 id="_4-全局说明" tabindex="-1">4. 全局说明 <a class="header-anchor" href="#_4-全局说明" aria-label="Permalink to &quot;4. 全局说明&quot;">​</a></h2><p>① 入库 / 出库 / 移库 / 盘库四类业务单据的<strong>单据编号</strong>，由前端在新增时按 <code>前缀 + 月日 + 4 位随机数</code> 默认生成（入库 <code>RK</code>、出库 <code>CK</code>、移库 <code>YK</code>、盘库 <code>PK</code>，如 <code>RK05151234</code>），允许用户手动修改，由后端校验唯一性。</p><p>② 上述四类单据均为「<strong>主子表</strong>」结构。先新增主表记录，保存后弹窗自动切换为编辑模式，再在弹窗中维护明细子表。</p><p>③ 单据统一采用「<strong>草稿 → 已完成 / 已作废</strong>」两阶段状态流转：草稿阶段为单据起草，可自由编辑；<strong>&quot;完成&quot;操作</strong>才触发库存事务，将变更写入 <code>wms_inventory</code>（当前库存）与 <code>wms_inventory_history</code>（流水），同时把单据状态置为&quot;已完成&quot;。</p><p>④ 首页基础报表（<code>WMS 系统 -&gt; 首页</code>）由 WmsHomeStatisticsController 提供，<strong>直接聚合</strong> <code>wms_inventory</code> 与 <code>wms_inventory_history</code> 的关键指标输出，不写入新表。</p>',29)])])}const f=o(l,[["render",m]]);export{y as __pageData,f as default};
